implementation:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <MagickCore/MagickCore.h>

void UnregisterINLINEImage(void) {
  UnregisterMagickInfo("INLINE");
  UnregisterMagickInfo("DATA");
}

MagickBooleanType WriteINLINEImage(const ImageInfo *image_info, Image *image) {
  Image
    *clone_image;

  MagickBooleanType
    status;

  MagickInfo
    *magick_info;

  char
    *base64_data;

  size_t
    base64_length;

  if (!image_info || !image) {
    return MagickFalse;
  }

  if (image_info->debug) {
    (void) LogMagickEvent(CoderEvent, GetMagickModule(), "filename: %s", image_info->filename);
  }

  magick_info = GetMagickInfo(image_info->magick, &image->exception);
  if (!magick_info || !magick_info->decoder) {
    return MagickFalse;
  }

  clone_image = CloneImage(image, 0, 0, MagickTrue, &image->exception);
  if (!clone_image) {
    return MagickFalse;
  }

  status = BlobImage(clone_image, &image->exception);
  if (!status) {
    clone_image = DestroyImage(clone_image);
    return MagickFalse;
  }

  base64_length = (clone_image->blob->length * 4) / 3 + 4;
  base64_data = (char *) AcquireMemory(base64_length);
  if (!base64_data) {
    clone_image = DestroyImage(clone_image);
    return MagickFalse;
  }

  (void) Base64Encode(clone_image->blob->length, clone_image->blob->data, base64_data, base64_length);

  clone_image->blob = CloneBlob(base64_length, base64_data);
  if (!clone_image->blob) {
    base64_data = RelinquishMemory(base64_data);
    clone_image = DestroyImage(clone_image);
    return MagickFalse;
  }

  status = WriteBlobImage(clone_image, &image->exception);

  base64_data = RelinquishMemory(base64_data);
  clone_image = DestroyImage(clone_image);

  return status;
}
